import math


def distance_2d(x1, y1, x2, y2):
    delta_x = x2 - x1
    delta_y = y2 - y1
    return math.sqrt(delta_x * delta_x + delta_y * delta_y)


def parse_point(point_text):
    coordinate_parts = point_text.replace("(", "").replace(")", "").split(",")
    if len(coordinate_parts) != 2:
        raise ValueError("a point needs exactly two coordinates: " + point_text)
    x_value = float(coordinate_parts[0].strip())
    y_value = float(coordinate_parts[1].strip())
    return x_value, y_value


def parse_point_list(point_texts):
    parsed_points = []
    for single_text in point_texts:
        parsed_points.append(parse_point(single_text))
    return parsed_points


def path_length(point_list):
    total_length = 0.0
    for segment_index in range(1, len(point_list)):
        previous_x, previous_y = point_list[segment_index - 1]
        current_x, current_y = point_list[segment_index]
        total_length += distance_2d(previous_x, previous_y, current_x, current_y)
    return total_length


def longest_segment(point_list):
    max_distance = 0.0
    max_index = 0
    for segment_index in range(1, len(point_list)):
        start_x, start_y = point_list[segment_index - 1]
        end_x, end_y = point_list[segment_index]
        segment_distance = distance_2d(start_x, start_y, end_x, end_y)
        if segment_distance > max_distance:
            max_distance = segment_distance
            max_index = segment_index - 1
    return max_index, max_distance


def nearest_pair(point_list):
    best_pair = (0, 0)
    best_distance = float("inf")
    total_count = len(point_list)
    for first_index in range(total_count):
        for second_index in range(first_index + 1, total_count):
            first_x, first_y = point_list[first_index]
            second_x, second_y = point_list[second_index]
            pair_distance = distance_2d(first_x, first_y, second_x, second_y)
            if pair_distance < best_distance:
                best_distance = pair_distance
                best_pair = (first_index, second_index)
    return best_pair, best_distance


def format_report(point_list):
    report_lines = ["points: " + str(len(point_list))]
    report_lines.append("path length: {0:.4f}".format(path_length(point_list)))
    longest_index, longest_distance = longest_segment(point_list)
    report_lines.append(
        "longest segment: {0} -> {1} ({2:.4f})".format(
            longest_index, longest_index + 1, longest_distance
        )
    )
    (left_index, right_index), closest_distance = nearest_pair(point_list)
    report_lines.append(
        "closest pair: {0} and {1} ({2:.4f})".format(
            left_index, right_index, closest_distance
        )
    )
    return "\n".join(report_lines)


def main():
    raw_points = ["(0, 0)", "(3, 4)", "(3, 4)", "(-1, 6.5)", "(10, 0)"]
    walked_points = parse_point_list(raw_points)
    print(distance_2d(0, 0, 3, 4))
    print(distance_2d(1, 1, 1, 1))
    print(format_report(walked_points))


if __name__ == "__main__":
    main()

