import math


def distance_2d(x1, y1, x2, y2):
    deltaX = x2 - x1
    deltaY = y2 - y1
    return math.sqrt(deltaX * deltaX + deltaY * deltaY)


def parsePoint(pointText):
    coordinateParts = pointText.replace("(", "").replace(")", "").split(",")
    if len(coordinateParts) != 2:
        raise ValueError("a point needs exactly two coordinates: " + pointText)
    xValue = float(coordinateParts[0].strip())
    yValue = float(coordinateParts[1].strip())
    return xValue, yValue


def parsePointList(pointTexts):
    parsedPoints = []
    for singleText in pointTexts:
        parsedPoints.append(parsePoint(singleText))
    return parsedPoints


def pathLength(pointList):
    totalLength = 0.0
    for segmentIndex in range(1, len(pointList)):
        previousX, previousY = pointList[segmentIndex - 1]
        currentX, currentY = pointList[segmentIndex]
        totalLength += distance_2d(previousX, previousY, currentX, currentY)
    return totalLength


def longestSegment(pointList):
    maxDistance = 0.0
    maxIndex = 0
    for segmentIndex in range(1, len(pointList)):
        startX, startY = pointList[segmentIndex - 1]
        endX, endY = pointList[segmentIndex]
        segmentDistance = distance_2d(startX, startY, endX, endY)
        if segmentDistance > maxDistance:
            maxDistance = segmentDistance
            maxIndex = segmentIndex - 1
    return maxIndex, maxDistance


def nearestPair(pointList):
    bestPair = (0, 0)
    bestDistance = float("inf")
    totalCount = len(pointList)
    for firstIndex in range(totalCount):
        for secondIndex in range(firstIndex + 1, totalCount):
            firstX, firstY = pointList[firstIndex]
            secondX, secondY = pointList[secondIndex]
            pairDistance = distance_2d(firstX, firstY, secondX, secondY)
            if pairDistance < bestDistance:
                bestDistance = pairDistance
                bestPair = (firstIndex, secondIndex)
    return bestPair, bestDistance


def formatReport(pointList):
    reportLines = ["points: " + str(len(pointList))]
    reportLines.append("path length: {0:.4f}".format(pathLength(pointList)))
    longestIndex, longestDistance = longestSegment(pointList)
    reportLines.append(
        "longest segment: {0} -> {1} ({2:.4f})".format(
            longestIndex, longestIndex + 1, longestDistance
        )
    )
