def sum_digits(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("sum_digits expects an integer")
    if n < 0:
        raise ValueError("sum_digits expects a non-negative integer")
    running_total = 0
    remaining_value = n
    while remaining_value > 0:
        remaining_value, current_digit = divmod(remaining_value, 10)
        running_total += current_digit
    return running_total


def digital_root(n):
    collapsed_value = sum_digits(n)
    while collapsed_value >= 10:
        collapsed_value = sum_digits(collapsed_value)
    return collapsed_value


def parse_number_tokens(raw_text):
    parsed_numbers = []
    for raw_token in raw_text.split():
        cleaned_token = raw_token.strip(",;")
        if not cleaned_token.isdigit():
            raise ValueError("not a non-negative integer: " + raw_token)
        parsed_numbers.append(int(cleaned_token))
    return parsed_numbers


def build_digit_report(input_list):
    report_rows = []
    for source_number in input_list:
        report_rows.append((source_number, sum_digits(source_number), digital_root(source_number)))
    return report_rows


def format_report(report_rows):
    number_width = max((len(str(row[0])) for row in report_rows), default=1)
    formatted_lines = []
    for source_number, digit_sum, root_value in report_rows:
        formatted_lines.append(
            "{:>{width}} -> sum {:>3}, digital root {}".format(
                source_number, digit_sum, root_value, width=number_width
            )
        )
    return "\n".join(formatted_lines)


def summarize_report(report_rows):
    total_sum = sum(row[1] for row in report_rows)
    max_value = max(row[1] for row in report_rows)
    busiest_number = next(row[0] for row in report_rows if row[1] == max_value)
    return total_sum, max_value, busiest_number


def main():
    sample_text = "123 9 0 4096, 999999; 10203040"
    number_list = parse_number_tokens(sample_text)
    digit_report = build_digit_report(number_list)
    print(format_report(digit_report))
    total_sum, max_value, busiest_number = summarize_report(digit_report)
    print("combined digit sum: {}".format(total_sum))
    print("largest digit sum: {} (from {})".format(max_value, busiest_number))


if __name__ == "__main__":
    main()

