def nth_fibonacci(desired_index_position):
    """
    Calculates the Nth Fibonacci number starting with 0, 1, 1, 2...
    """
    if desired_index_position < 0:
        raise ValueError("Input index must be a non-negative integer.")
    elif desired_index_position == 0:
        return 0
    elif desired_index_position == 1:
        return 1
    else:
        previous_number = 0
        current_sequence_number = 1
        for _current_iteration_count in range(2, desired_index_position + 1):
            next_fib_value = previous_number + current_sequence_number
            previous_number = current_sequence_number
            current_sequence_number = next_fib_value
        return current_sequence_number

