def calculate_weighted_average(list_of_values, list_of_weights):
    """Calculates the weighted average of a list of values and their corresponding weights."""
    if not list_of_values or not list_of_weights:
        raise ValueError("Input lists cannot be empty.")
    if len(list_of_values) != len(list_of_weights):
        raise ValueError("Values and weights lists must have the same length.")

    sum_of_products = 0.0
    total_weight_sum = 0.0

    for current_index in range(len(list_of_values)):
        current_value = list_of_values[current_index]
        current_weight = list_of_weights[current_index]
        sum_of_products += current_value * current_weight
        total_weight_sum += current_weight

    if total_weight_sum == 0:
        raise ValueError("Sum of weights cannot be zero.")

    final_calculated_average = sum_of_products / total_weight_sum
    return final_calculated_average

