class BankAccount:
    def __init__(self, initial_account_balance):
        self.current_account_balance = initial_account_balance
        self.minimum_allowed_balance = 0

    def deposit_funds(self, deposit_amount):
        if deposit_amount <= 0:
            return False
        self.current_account_balance += deposit_amount
        return True

    def withdraw_funds(self, withdrawal_amount):
        if withdrawal_amount <= 0:
            return False
        if self.current_account_balance - withdrawal_amount >= self.minimum_allowed_balance:
            self.current_account_balance -= withdrawal_amount
            return True
        return False

    def get_current_balance(self):
        return self.current_account_balance

    def set_minimum_balance(self, new_minimum_balance):
        if new_minimum_balance >= 0:
            self.minimum_allowed_balance = new_minimum_balance
            return True
        return False

    def check_for_positive_balance(self):
        return self.current_account_balance > 0

    def process_transaction(self, transaction_type, transaction_value):
        if transaction_type == "deposit":
            return self.deposit_funds(transaction_value)
        elif transaction_type == "withdraw":
            return self.withdraw_funds(transaction_value)
        return False

