    def depositFunds(self, depositAmount):
        if depositAmount <= 0:
            return False
        self.currentAccountBalance += depositAmount
        return True

    def withdrawFunds(self, withdrawalAmount):
        if withdrawalAmount <= 0:
            return False
        if self.currentAccountBalance - withdrawalAmount >= self.minimumAllowedBalance:
            self.currentAccountBalance -= withdrawalAmount
            return True
        return False

    def getCurrentBalance(self):
        return self.currentAccountBalance

    def setMinimumBalance(self, newMinimumBalance):
        if newMinimumBalance >= 0:
            self.minimumAllowedBalance = newMinimumBalance
            return True
        return False

    def checkForPositiveBalance(self):
        return self.currentAccountBalance > 0

    def processTransaction(self, transactionType, transactionValue):
        if transactionType == "deposit":
            return self.depositFunds(transactionValue)
        elif transactionType == "withdraw":
            return self.withdrawFunds(transactionValue)
        return False

