import calendar
import datetime


def validate_month_input(year, month):
    if not isinstance(year, int) or not isinstance(month, int):
        raise TypeError("year and month must be integers")
    if month < 1 or month > 12:
        raise ValueError("month must be between 1 and 12")
    if year < datetime.MINYEAR or year > datetime.MAXYEAR:
        raise ValueError("year is outside the supported range")


def count_business_days(year, month):
    validate_month_input(year, month)
    days_in_month = calendar.monthrange(year, month)[1]
    business_day_count = 0
    for day_number in range(1, days_in_month + 1):
        current_date = datetime.date(year, month, day_number)
        if current_date.weekday() < 5:
            business_day_count += 1
    return business_day_count


def list_business_days(year, month):
    validate_month_input(year, month)
    days_in_month = calendar.monthrange(year, month)[1]
    business_date_list = []
    for day_number in range(1, days_in_month + 1):
        current_date = datetime.date(year, month, day_number)
        if current_date.weekday() < 5:
            business_date_list.append(current_date)
    return business_date_list


def count_business_days_in_year(year):
    monthly_counts = {}
    for month_number in range(1, 13):
        monthly_counts[month_number] = count_business_days(year, month_number)
    return monthly_counts


def format_month_report(year, month):
    business_dates = list_business_days(year, month)
    month_label = calendar.month_name[month]
    total_days = calendar.monthrange(year, month)[1]
    weekend_count = total_days - len(business_dates)
    first_business_day = business_dates[0]
    last_business_day = business_dates[-1]
    report_lines = [
        "{} {}".format(month_label, year),
        "  total days:     {}".format(total_days),
        "  business days:  {}".format(len(business_dates)),
        "  weekend days:   {}".format(weekend_count),
        "  first workday:  {}".format(first_business_day.isoformat()),
        "  last workday:   {}".format(last_business_day.isoformat()),
    ]
    return "\n".join(report_lines)


def format_year_summary(year):
    monthly_counts = count_business_days_in_year(year)
    yearly_total = sum(monthly_counts.values())
    summary_lines = ["Business days per month in {}".format(year)]
    for month_number, month_total in monthly_counts.items():
        short_label = calendar.month_abbr[month_number]
        summary_lines.append("  {:<4} {:>3}".format(short_label, month_total))
    summary_lines.append("  {:<4} {:>3}".format("all", yearly_total))
    return "\n".join(summary_lines)


def main():
    target_year = 2023
    for target_month in (10, 11):
        print(format_month_report(target_year, target_month))
        print()
    print(format_year_summary(target_year))


if __name__ == "__main__":
    main()

